package in.indianweb.browser;import android.app.Activity;import android.os.Bundle;import android.webkit.WebView;public class MainActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);WebView v=new WebView(this);v.getSettings().setJavaScriptEnabled(true);v.getSettings().setDomStorageEnabled(true);v.loadUrl("file:///android_asset/index.html");setContentView(v);}}